use lsp_types::{
    Diagnostic, DiagnosticSeverity, DocumentSymbol, Range, SymbolKind,
    TextDocumentContentChangeEvent,
};
use tree_sitter::{Node, Parser};
use tree_sitter_language::LanguageFn;

extern "C" {
    fn tree_sitter_denotate() -> *const ();
}

pub fn parser() -> Parser {
    // Generated by the pinned CLI and compiled by this crate's build script.
    let language = unsafe { LanguageFn::from_raw(tree_sitter_denotate) };
    denotate_editor::parser(language.into()).expect("compatible generated grammar")
}

/// B's syntax presentation and optional timing wrap the shared text/tree snapshot.
pub struct Document(denotate_editor::Document);

impl std::ops::Deref for Document {
    type Target = denotate_editor::Document;
    fn deref(&self) -> &Self::Target {
        &self.0
    }
}
impl AsRef<denotate_editor::Document> for Document {
    fn as_ref(&self) -> &denotate_editor::Document {
        &self.0
    }
}
impl Document {
    pub fn new(parser: &mut Parser, text: String, version: i32, open: bool) -> Self {
        let _timer = crate::timing::interval("parseAndText");
        Self(denotate_editor::Document::new(parser, text, version, open))
    }
    pub fn changed(
        &self,
        parser: &mut Parser,
        changes: &[TextDocumentContentChangeEvent],
        version: i32,
    ) -> Result<Self, &'static str> {
        let _timer = crate::timing::interval("parseAndText");
        self.0.changed(parser, changes, version).map(Self)
    }

    fn range(&self, node: Node<'_>) -> Range {
        Range::new(
            self.position(node.start_byte()),
            self.position(node.end_byte()),
        )
    }

    pub fn diagnostics(&self) -> Vec<Diagnostic> {
        let mut result = Vec::new();
        self.visit_errors(self.tree.root_node(), &mut result);
        result
    }

    fn visit_errors(&self, node: Node<'_>, result: &mut Vec<Diagnostic>) {
        // Tree-sitter's reserved set applies to its `identifier` word token,
        // not the separate lowercase `constant` token. Enforce the same lexical
        // restriction here, before semantic analysis (including declarations).
        let reserved_constant =
            node.kind() == "constant" && crate::projection::reserved(&self.text[node.byte_range()]);
        if node.is_error() || node.is_missing() || reserved_constant {
            result.push(Diagnostic {
                range: self.range(node),
                severity: Some(DiagnosticSeverity::ERROR),
                source: Some("denotate-syntax".into()),
                message: if reserved_constant {
                    format!(
                        "Reserved word '{}' cannot be a constant.",
                        &self.text[node.byte_range()]
                    )
                } else if node.is_missing() {
                    format!("Expected {}.", node.kind())
                } else {
                    "Unexpected syntax.".into()
                },
                ..Diagnostic::default()
            });
            // One diagnostic per error region, rather than every descendant.
            return;
        }
        for child in node.children(&mut node.walk()) {
            self.visit_errors(child, result);
        }
    }

    pub fn symbols(&self) -> Vec<DocumentSymbol> {
        let mut result = Vec::new();
        self.collect_symbols(self.tree.root_node(), &mut result);
        result
    }

    fn collect_symbols(&self, parent: Node<'_>, result: &mut Vec<DocumentSymbol>) {
        for node in parent.named_children(&mut parent.walk()) {
            let kind = match node.kind() {
                "module" | "import" => SymbolKind::MODULE,
                "sort" => SymbolKind::CLASS,
                "constants" => SymbolKind::CONSTANT,
                "relation" => SymbolKind::FUNCTION,
                "statement" => SymbolKind::OPERATOR,
                "ERROR" => {
                    self.collect_symbols(node, result);
                    continue;
                }
                _ => continue,
            };
            let selection = if node.kind() == "statement" {
                node.child_by_field_name("head")
                    .and_then(|head| head.child_by_field_name("name"))
            } else {
                node.child_by_field_name("name")
            };
            let Some(selection) = selection.filter(|n| !n.is_missing()) else {
                continue;
            };
            let mut tokens = Vec::new();
            self.tokens(node, &mut tokens);
            let body = tokens.iter().position(|token| *token == ":-");
            if let Some(index) = body {
                tokens.truncate(index);
            }
            tokens.retain(|token| *token != ";" && *token != "\u{feff}");
            let mut label = String::new();
            for (i, token) in tokens.iter().enumerate() {
                if i > 0 && !matches!(*token, "(" | ")" | "," | ":") && tokens[i - 1] != "(" {
                    label.push(' ');
                }
                label.push_str(token);
            }
            if body.is_some() {
                label.push_str(" :- …");
            }
            #[allow(deprecated)]
            result.push(DocumentSymbol {
                name: label,
                detail: None,
                kind,
                tags: None,
                deprecated: None,
                range: if node.kind() == "module" {
                    self.range(selection)
                } else {
                    self.range(node)
                },
                selection_range: self.range(selection),
                children: None,
            });
        }
    }

    fn tokens<'a>(&'a self, node: Node<'_>, tokens: &mut Vec<&'a str>) {
        if node.kind() == "comment" || node.is_missing() {
            return;
        }
        if node.child_count() == 0 {
            tokens.push(&self.text[node.byte_range()]);
        } else {
            for child in node.children(&mut node.walk()) {
                self.tokens(child, tokens);
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use lsp_types::Position;
    use serde_json::Value;
    use std::{fs, path::Path};
    use tree_sitter::Point;

    fn equivalent(incremental: &Document) {
        let fresh = Document::new(
            &mut parser(),
            incremental.text.clone(),
            incremental.version,
            true,
        );
        fn shape(
            node: Node<'_>,
        ) -> Vec<(String, std::ops::Range<usize>, Point, Point, bool, bool)> {
            let mut result = vec![(
                node.kind().into(),
                node.byte_range(),
                node.start_position(),
                node.end_position(),
                node.is_error(),
                node.is_missing(),
            )];
            for child in node.children(&mut node.walk()) {
                result.extend(shape(child));
            }
            result
        }
        assert_eq!(
            shape(incremental.tree.root_node()),
            shape(fresh.tree.root_node()),
            "{}",
            incremental.text
        );
        assert_eq!(incremental.diagnostics(), fresh.diagnostics());
        assert_eq!(incremental.symbols(), fresh.symbols());
        let uri = lsp_types::Url::parse("file:///example.den").unwrap();
        let a = crate::projection::Projection::new(incremental, &uri);
        let b = crate::projection::Projection::new(&fresh, &uri);
        assert_eq!(a.input, b.input);
        assert_eq!(a.anchors, b.anchors);
        assert_eq!(a.rule_anchors, b.rule_anchors);
    }

    fn change(
        doc: &Document,
        start: usize,
        end: usize,
        text: &str,
    ) -> TextDocumentContentChangeEvent {
        TextDocumentContentChangeEvent {
            range: Some(Range::new(doc.position(start), doc.position(end))),
            range_length: None,
            text: text.into(),
        }
    }

    #[test]
    fn incremental_and_fresh_agree_through_damage_and_repair_for_every_fixture() {
        let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../fixtures");
        let manifest: Value =
            serde_json::from_str(&fs::read_to_string(root.join("syntax.json")).unwrap()).unwrap();
        let mut parser = parser();
        for case in manifest["cases"].as_array().unwrap() {
            let text = fs::read_to_string(root.join(case["file"].as_str().unwrap())).unwrap();
            let doc = Document::new(&mut parser, text, 1, true);
            let insertion = change(&doc, 0, 0, "// 🦀\r\n");
            let moved = doc.changed(&mut parser, &[insertion], 2).unwrap();
            equivalent(&moved);
            if let Some(at) = moved.text.find(';') {
                let damaged = moved
                    .changed(&mut parser, &[change(&moved, at, at + 1, "")], 3)
                    .unwrap();
                equivalent(&damaged);
                let repaired = damaged
                    .changed(&mut parser, &[change(&damaged, at, at, ";")], 4)
                    .unwrap();
                equivalent(&repaired);
                assert_eq!(repaired.text, moved.text);
            }
        }
    }

    #[test]
    fn sequential_ranges_handle_astral_text_crlf_lone_cr_and_reject_invalid_edits_atomically() {
        let mut parser = parser();
        let doc = Document::new(
            &mut parser,
            "module example; // 🦀\r\nsort S;\rrelation r(x: S);".into(),
            1,
            true,
        );
        let end = doc.text.find('\r').unwrap();
        let edits = [
            change(&doc, end, end, " hello"),
            change(&doc, end, end, "!"),
        ];
        let result = doc.changed(&mut parser, &edits, 2).unwrap();
        assert!(result.text.contains("🦀! hello\r\n"));
        equivalent(&result);
        let at = result.text.find("relation").unwrap();
        let result = result
            .changed(&mut parser, &[change(&result, at, at, "// 🦀\r")], 3)
            .unwrap();
        equivalent(&result);
        let invalid = TextDocumentContentChangeEvent {
            range: Some(Range::new(Position::new(0, 2), Position::new(0, 1))),
            range_length: None,
            text: "x".into(),
        };
        assert!(doc
            .changed(&mut parser, &[change(&doc, 0, 0, " "), invalid], 4)
            .is_err());
        assert_eq!(doc.version, 1);
        equivalent(&doc);
        let full = TextDocumentContentChangeEvent {
            range: None,
            range_length: None,
            text: "module example;\nsort Longer;".into(),
        };
        let edit = TextDocumentContentChangeEvent {
            range: Some(Range::new(Position::new(1, 5), Position::new(1, 11))),
            range_length: None,
            text: "S".into(),
        };
        let mixed = doc.changed(&mut parser, &[full, edit], 5).unwrap();
        assert_eq!(mixed.text, "module example;\nsort S;");
        equivalent(&mixed);
    }

    #[test]
    fn shared_syntax_manifest() {
        let fixtures = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../fixtures");
        let manifest: Value =
            serde_json::from_str(&fs::read_to_string(fixtures.join("syntax.json")).unwrap())
                .unwrap();
        let mut parser = parser();
        let mut failures = Vec::new();
        for case in manifest["cases"].as_array().unwrap() {
            let file = case["file"].as_str().unwrap();
            let text = fs::read_to_string(fixtures.join(file)).unwrap();
            let doc = Document::new(&mut parser, text, 1, true);
            if doc.diagnostics().is_empty() != (case["extended"] == "accept") {
                failures.push(format!(
                    "{file}: expected {}\n{}\n{:?}",
                    case["extended"],
                    doc.tree.root_node().to_sexp(),
                    doc.diagnostics()
                ));
            }
        }
        assert!(failures.is_empty(), "{}", failures.join("\n"));
        assert_eq!(manifest["cases"].as_array().unwrap().len(), 65);
    }

    #[test]
    fn reserved_constants_in_each_position_and_keyword_prefixes() {
        let mut parser = parser();
        for word in ["module", "use", "sort", "const", "relation", "input"] {
            for suffix in ["", "_value"] {
                let name = format!("{word}{suffix}");
                for statement in [
                    format!("const {name}: S;"),
                    format!("r({name});"),
                    format!("r(X) :- r({name});"),
                    format!("r(X) :- !r({name});"),
                ] {
                    let text = format!("module example; sort S; relation r(value: S); {statement}");
                    let doc = Document::new(&mut parser, text, 1, true);
                    let diagnostics = doc.diagnostics();
                    if suffix.is_empty() {
                        assert_eq!(diagnostics.len(), 1, "{statement}");
                        assert!(
                            diagnostics[0].message.contains("Reserved word"),
                            "{statement}"
                        );
                        let start = doc.text.rfind(word).unwrap();
                        assert_eq!(
                            diagnostics[0].range,
                            Range::new(doc.position(start), doc.position(start + word.len()))
                        );
                    } else {
                        assert!(diagnostics.is_empty(), "{statement}: {diagnostics:?}");
                    }
                }
            }
        }
    }

    #[test]
    fn utf16_positions_and_line_endings() {
        let text = "// 🦀\r\nsort Slot;\rsort Source;\n";
        let doc = Document::new(&mut parser(), text.into(), 1, true);
        assert_eq!(doc.position("// 🦀".len()), Position::new(0, 5));
        assert_eq!(
            doc.position(text.find("Slot").unwrap()),
            Position::new(1, 5)
        );
        assert_eq!(
            doc.position(text.find("Source").unwrap()),
            Position::new(2, 5)
        );
    }

    #[test]
    fn positions_clamp_to_line_document_and_unicode_scalar_boundaries() {
        for eol in ["\n", "\r\n", "\r"] {
            let text = format!("// 🦀{eol}sort S;");
            let doc = Document::new(&mut parser(), text.clone(), 1, true);
            assert_eq!(doc.offset(Position::new(0, 999)), Some("// 🦀".len()));
            assert_eq!(doc.offset(Position::new(99, 0)), Some(text.len()));
            assert_eq!(doc.offset(Position::new(1, 999)), Some(text.len()));
            assert_eq!(doc.offset(Position::new(0, 4)), Some(3));
            let insert = TextDocumentContentChangeEvent {
                range: Some(Range::new(Position::new(0, 4), Position::new(0, 4))),
                range_length: None,
                text: "ok".into(),
            };
            let changed = doc.changed(&mut parser(), &[insert], 2).unwrap();
            assert!(changed.text.starts_with("// ok🦀"));
            equivalent(&changed);
        }
    }
}
